// n8n Notion databasePage:getAll (simplify:true) achata as properties como `property_<minusculo>`.
// 'Drive_folder' -> property_drive_folder, 'Brand' -> property_brand, 'Page_id' -> property_page_id,
// 'Niche' -> property_niche (array), titulo -> page.name. Fallbacks pro caso de simplify:false.
const inp = $json;
const page = inp.page || inp;
const cfg = inp.cfg || {};
const prop = page.properties || {};
const rt = (x) => (x && x.rich_text ? x.rich_text.map((t) => t.plain_text).join('') : '');
const pageId = page.id || '';
const driveUrl = page.property_drive_folder || page.Drive_folder || (prop.Drive_folder && prop.Drive_folder.url) || '';
const mm = String(driveUrl).match(/folders\/([A-Za-z0-9_-]+)/);
const folderId = mm ? mm[1] : '';
const brand = page.property_brand || page.Brand || rt(prop.Brand) || '';
const pageIdRaw = page.property_page_id || page.Page_id || rt(prop.Page_id) || '';
let niche = page.property_niche || page.Niche;
if (Array.isArray(niche)) niche = niche.map((n) => (n && n.name ? n.name : n)).join(', ');
if (!niche && prop.Niche && Array.isArray(prop.Niche.multi_select)) niche = prop.Niche.multi_select.map((n) => n.name).join(', ');
niche = niche || '';
const title = page.name || page.property_name || page.Name || (prop.Name && prop.Name.title ? prop.Name.title.map((t) => t.plain_text).join('') : '') || 'Teardown';
return [{ json: { pageId, folderId, brand, page_id: String(pageIdRaw), niche, title, driveUrl, cfg } }];

const files = $input.all().map((i) => i.json).filter((f) => f && f.id && f.name);
const cfg = $('Parse pagina').first().json.cfg || {};
const cap = cfg.maxAdsAnalisados || 4;
const ctx = files.find((f) => f.name === 'contexto.json');
const imgs = files.filter((f) => /\.(jpe?g|png)$/i.test(f.name) && /_img|_cover/i.test(f.name)).slice(0, cap).map((f) => ({ id: f.id, name: f.name }));
const sem_dados = !ctx || imgs.length === 0;
return [{ json: { contextoFileId: ctx ? ctx.id : null, imageFileIds: imgs, sem_dados, folderId: $('Parse pagina').first().json.folderId } }];

const imgs = $('Separar').first().json.imageFileIds || [];
if (!imgs.length) return [{ json: { __none: true } }];
return imgs.map((x) => ({ json: { fileId: x.id, name: x.name } }));

// Comunidade OpenRouter (Analyze Content): 1 item com json.prompt (texto) + binary.data (1a imagem).
const p = $('Parse pagina').first().json;
const cfg = p.cfg || {};
let ctx = {};
try { const cj = $('contexto -> json').first().json; ctx = cj && cj.data ? cj.data : (cj || {}); } catch (e) { ctx = {}; }
const anuncios = (ctx.anuncios || []).slice(0, cfg.maxAdsAnalisados || 4);
const copy = anuncios.map((a, i) => `Anuncio ${i+1} [${a.formato||'?'}] CTA:${a.cta||'-'} | Headline: ${a.headline||'-'} | Texto: ${a.primary_text||'-'}`).join('\n') || '(copy nao disponivel)';
const meta = `Marca: ${ctx.marca||p.brand} | Nicho: ${p.niche||'-'} | ${ctx.ads_ativos||'?'} ads ativos | ${ctx.dias_no_ar||'?'} dias no ar`;
const prompt = [
  'Voce e Diretor de Criacao + Copywriter de performance senior da Perseo (agencia de UGC pra Meta Ads).',
  'Faca o TEARDOWN do criativo de anuncio do concorrente. A imagem anexa e um criativo ativo dessa marca.',
  '', meta, '', 'COPY DOS ANUNCIOS:', copy, '',
  'RUBRICA: Hook (peso 40, primeiros 3s ou 1a linha): para o scroll? especifico? funciona no mudo? | Desenvolvimento (peso 30): sustenta o hook? prova concreta? staircase error? | CTA (peso 30): claro, urgencia, unico? | Estagio de consciencia 1-5 e se e cold-ok ou retargeting-only (80/10/10) | Framework (PAS/AIDA/HSO/BAB/BITE) + angulo psicologico | Criativo nativo? parece conteudo ou propaganda? | Risco de compliance Meta | O GAP: o que a Perseo faria diferente (angulo + hook + hipotese de teste), 1-3 frases.',
  'SAIDA em prosa curta com NOTA GERAL X/10 e nota por criterio. No fim, um bloco json entre tres crases: {"nota_geral":n,"hook_score":n,"desenvolvimento_score":n,"cta_score":n,"estagio":"N nome","cold_ok":true,"framework":"...","angulo":"...","nativo":true,"o_que_funciona":["..."],"gap":"..."}'
].join('\n');
const items = $input.all();
const withBin = items.find((i) => i.binary && i.binary.data);
return [{ json: { prompt, meta, brand: p.brand }, binary: withBin ? withBin.binary : {} }];

// extracao robusta: o node community pode devolver text/content/response/output/... ou o shape OpenAI.
const r = $json;
let raw = '';
if (typeof r === 'string') raw = r;
else raw = r.text || r.content || r.response || r.output || r.analysis || r.result || r.message
  || (r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content)
  || (r.data && (r.data.text || r.data.content)) || '';
if (!raw && r && typeof r === 'object') raw = JSON.stringify(r);
raw = String(raw).trim();
const p = $('Parse pagina').first().json;
const meta = $('Montar prompt visao').first().json.meta || '';
const now = new Date().toISOString().slice(0, 10);
let structured = { teardown_raw: raw };
const jm = raw.match(/```json\s*([\s\S]+?)```/i);
if (jm) { try { structured = Object.assign({}, JSON.parse(jm[1]), { teardown_raw: raw }); } catch (e) {} }
structured.brand = p.brand;
structured.page_id = p.page_id;
structured.niche = p.niche;
structured.analyzed_at = now;
const prosa = raw.replace(/```json[\s\S]+?```/i, '').trim();
const texto = `TEARDOWN - ${p.brand} - ${p.niche || '-'} - ${now}\n${meta}\n\n${prosa}\n`;
const md = `## Teardown (auto - ${now})\n\n${meta}\n\n${prosa}\n`;
return [{ json: { texto, md, structured, brand: p.brand, pageId: p.pageId, page_id: p.page_id } }];
